function CIRCUIT_LOWER_BOUND(objects, orbit_dim, repMult, indices, f, B):
    for g in objects:
        if orbit_dim(g) <= B*B:
            if FIND_OBSTRUCTION(repMult, f, g, indices) is NONE:
                return NONE          # incomplete catalog: cannot conclude
    return B                          # certified: circuit_size(f) > B

function BARRIER_MIN_WEIGHT(exp_const c, level n):
    require c >= 1 and n >= 1
    return 2 ** (c * n)               # certified lower bound on any separator's maxWeight
